using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json.Linq;
public static class BFFMeasureRefine {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B4_Circular.unity"))throw new Exception("Saved B4 edit required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B4_")).transform;var path=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../SourceAssets/B4_FullFloor/refinements_measurement.json"));var changes=JArray.Parse(File.ReadAllText(path));foreach(var c in changes){var all=root.GetComponentsInChildren<Transform>(true);Transform t;if(c["cloneFrom"]!=null){var src=all.Single(a=>a.name==(string)c["cloneFrom"]);if(all.Any(a=>a.name==(string)c["name"]))throw new Exception("Already cloned");t=UnityEngine.Object.Instantiate(src.gameObject,src.parent).transform;t.name=(string)c["name"];}else t=all.Single(a=>a.name==(string)c["name"]);t.localPosition=new Vector3((float)c["position"][0],0,(float)c["position"][2]);t.localRotation=Quaternion.Euler(0,(float)c["yaw"],0);PrefabUtility.RecordPrefabInstancePropertyModifications(t);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);return new{refined=changes.Count};}
}
